package com.ecommerce.controller;
import com.ecommerce.dao.*; import com.ecommerce.util.View; import javax.servlet.*; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*; import java.io.IOException;
@WebServlet({"/","/home"}) public class HomeServlet extends HttpServlet{protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{try{Integer cat=req.getParameter("categoryId")==null||req.getParameter("categoryId").isEmpty()?null:Integer.parseInt(req.getParameter("categoryId"));req.setAttribute("categories",new CategoryDAO().findActive());req.setAttribute("products",new ProductDAO().findActive(cat,req.getParameter("q")));req.setAttribute("selectedCategory",cat);req.setAttribute("q",req.getParameter("q"));View.forward(req,resp,"index.jsp");}catch(Exception e){throw new ServletException(e);}}}
